-- Per-player fantasy-point splits (home/away, wins/losses, last-4 form)
-- over the trailing two regular seasons, powering the extra axis metrics
-- in /my-team's "My Analysis" scatter. One row per player, generated by
-- model/player_splits.R and published via
-- web/scripts/publish-player-splits.mjs. Public read, no tier gate --
-- same as the other tool tables the scatter already joins.
create table public.player_splits (
  player_name   text primary key,
  position      text,
  games         int,
  ppg           numeric,
  games_home    int,
  ppg_home      numeric,
  games_away    int,
  ppg_away      numeric,
  games_wins    int,
  ppg_wins      numeric,
  games_losses  int,
  ppg_losses    numeric,
  ppg_last4     numeric,
  updated_at    timestamptz not null default now()
);

alter table public.player_splits enable row level security;

create policy "Anyone can read player splits"
  on public.player_splits for select
  using (true);
